-- IMP-MSN-011: make selected immutable checklist executions part of authorisation evidence.
alter function public.ftf_evaluate_mission_readiness(uuid,uuid,timestamptz) rename to ftf_evaluate_mission_readiness_without_checklists;
create function public.ftf_evaluate_mission_readiness(p_organisation_id uuid,p_mission_id uuid,p_evaluated_at timestamptz default now())returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare base jsonb;checks jsonb;manifest jsonb;executions jsonb;begin
 base=public.ftf_evaluate_mission_readiness_without_checklists(p_organisation_id,p_mission_id,p_evaluated_at);if coalesce((base->>'notFound')::boolean,false)then return base;end if;checks=public.ftf_evaluate_mission_checklist_readiness(p_organisation_id,p_mission_id,'PRE_FLIGHT');
 select coalesce(jsonb_agg(to_jsonb(e)order by e.completed_at),'[]')into executions from public.checklist_executions e where e.organisation_id=p_organisation_id and e.mission_id=p_mission_id and e.lifecycle_stage='PRE_FLIGHT'and e.status='SUBMITTED';manifest=jsonb_set(base->'evidenceManifest','{preflight,checklists}',executions,true);base=jsonb_set(base,'{evidenceManifest}',manifest,true);base=jsonb_set(base,'{blockers}',coalesce(base->'blockers','[]')||coalesce(checks->'blockers','[]'),true);base=jsonb_set(base,'{categories,Controlled Checklists}',to_jsonb(case when(checks->>'ready')::boolean then'COMPLETE'else'OUTSTANDING'end),true);base=jsonb_set(base,'{completedSections}',coalesce(base->'completedSections','[]')||case when(checks->>'ready')::boolean then'["Controlled Checklists"]'::jsonb else'[]'::jsonb end,true);base=jsonb_set(base,'{outstandingSections}',coalesce(base->'outstandingSections','[]')||case when(checks->>'ready')::boolean then'[]'::jsonb else'["Controlled Checklists"]'::jsonb end,true);base=jsonb_set(base,'{ready}',to_jsonb(jsonb_array_length(base->'blockers')=0),true);base=jsonb_set(base,'{overallState}',to_jsonb(case when jsonb_array_length(base->'blockers')>0 then'BLOCKED'when jsonb_array_length(coalesce(base->'warnings','[]'))>0 then'WARNING'else'READY'end),true);return base;end$$;
revoke all on function public.ftf_evaluate_mission_readiness_without_checklists(uuid,uuid,timestamptz),public.ftf_evaluate_mission_readiness(uuid,uuid,timestamptz)from public,anon,authenticated;
grant execute on function public.ftf_evaluate_mission_readiness(uuid,uuid,timestamptz)to service_role;
